def get_lesson_seed(level: str, unit_id: str, lesson_type: str) -> dict[str, Any] | None:
    data = DATA.get(str(unit_id))
    if not data or data["level"] != str(level).upper():
        return None
    skill = str(lesson_type).lower()
    seed = {"unit_id": unit_id, "source": "curated_vietnamese", "title": data["title"], "objective": f"Phát triển kỹ năng {skill} theo chủ đề {data['title']} ở trình độ {data['level']}."}
    if skill == "grammar": seed.update(grammar=data["grammar"], examples=[data["grammar"]])
    elif skill == "vocabulary": seed.update(words=data["words"])
    elif skill == "reading": seed.update(text=data["text"], questions=["Ý chính của đoạn văn là gì?", "Nêu hai thông tin cụ thể.", "Giải thích một từ theo ngữ cảnh."])
    elif skill == "listening": seed.update(transcript=data["transcript"], questions=["Chủ đề chính là gì?", "Nêu hai thông tin đã nghe.", "Người nói đưa ra lý do hoặc kết luận nào?"])
    elif skill == "speaking": seed.update(prompt=data["speaking"], phrases=["Theo tôi,…", "Tuy nhiên,…", "Một lý do là…"], examples=[data["speaking"]])
    elif skill == "writing": seed.update(prompt=data["writing"], guidance=["Sắp xếp ý theo trình tự hợp lý.", "Dùng từ nối phù hợp.", "Kiểm tra ngữ pháp và chính tả."], examples=["Mở bài, phát triển ý và kết luận rõ ràng."])
    elif skill == "review": seed.update(questions=data["review"])
    else: return None
    return seed
